patch_result.patch:
--- a/parser.c
+++ b/parser.c
@@ -3397,7 +3397,7 @@
     int maxLength = (ctxt->options & XML_PARSE_HUGE) ?
                     XML_MAX_TEXT_LENGTH :
                     XML_MAX_NAME_LENGTH;
-    size_t startPosition = 0;
+    const xmlChar *start = NULL;

 #ifdef DEBUG
     nbParseNCNameComplex++;
@@ -3409,7 +3409,7 @@
     GROW;
     if (ctxt->instate == XML_PARSER_EOF)
         return(NULL);
-    startPosition = CUR_PTR - BASE_PTR;
+    start = CUR_PTR;
     c = CUR_CHAR(l);
     if ((c == ' ') || (c == '>') || (c == '/') || /* accelerators */
 	(!xmlIsNameStartChar(ctxt, c) || (c == ':'))) {
@@ -3447,7 +3447,7 @@
         xmlFatalErr(ctxt, XML_ERR_NAME_TOO_LONG, "NCName");
         return(NULL);
     }
-    return(xmlDictLookup(ctxt->dict, (BASE_PTR + startPosition), len));
+    return(xmlDictLookup(ctxt->dict, start, len));
 }

 /**

args:
@@ -3397,8 +3397,8 @@ xmlParseNCNameComplex(xmlParserCtxtPtr ctxt) {
     int maxLength = (ctxt->options & XML_PARSE_HUGE) ?
                     XML_MAX_TEXT_LENGTH :
                     XML_MAX_NAME_LENGTH;
-    size_t startPosition = 0;
+    const xmlChar *start = NULL;
@@ -3410,7 +3410,7 @@ xmlParseNCNameComplex(xmlParserCtxtPtr ctxt) {
     GROW;
     if (ctxt->instate == XML_PARSER_EOF)
         return(NULL);
-    startPosition = CUR_PTR - BASE_PTR;
+    start = CUR_PTR;
     c = CUR_CHAR(l);
@@ -3447,5 +3447,5 @@ xmlParseNCNameComplex(xmlParserCtxtPtr ctxt) {
         xmlFatalErr(ctxt, XML_ERR_NAME_TOO_LONG, "NCName");
         return(NULL);
     }
-    return(xmlDictLookup(ctxt->dict, (BASE_PTR + startPosition), len));
+    return(xmlDictLookup(ctxt->dict, start, len));
 }
